  {id:'adapters',name:'List network adapters',category:'Networking',icon:'⌁',description:'Check local adapter status and link speed.',keywords:['network adapters','adapter status','ethernet'],cmdlets:'Get-NetAdapter',dependencies:['NetAdapter'],parameters:[adapter],generate:v=>`Get-NetAdapter${optional(v,'adapter','Name')}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object Name, InterfaceDescription, Status, LinkSpeed, MacAddress`,requirements:local+' Adapter selection accepts wildcard patterns.'},
  {id:'dns-settings',name:'Get DNS server settings',category:'Networking',icon:'⌁',description:'See the DNS servers configured on local interfaces.',keywords:['dns settings','dns servers','dns configuration'],cmdlets:'Get-DnsClientServerAddress',dependencies:['DnsClient'],parameters:[adapter],generate:v=>`Get-DnsClientServerAddress${optional(v,'adapter','InterfaceAlias')}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object InterfaceAlias, AddressFamily, @{Name='ServerAddresses';Expression={$_.ServerAddresses -join ', '}}`,requirements:local},
  {id:'acl',name:'Read folder permissions',category:'File Management',icon:'▱',description:'Show ownership and individual access rules. This is not an effective-access calculation.',keywords:['folder permissions','acl','ownership','access rules'],cmdlets:'Get-Acl',parameters:[text('path','Folder or file path','C:\\Users\\Public','Uses a literal path; brackets and wildcard characters are treated as part of the name.',true)],generate:v=>`Get-Acl -LiteralPath ${q(v.path)}${v.verbose?' -Verbose':''} -ErrorAction Stop | ForEach-Object {\n    $ShellifyAcl = $_\n    $_.Access | Select-Object @{Name='Path';Expression={$ShellifyAcl.Path}}, @{Name='Owner';Expression={$ShellifyAcl.Owner}}, @{Name='IdentityReference';Expression={[string]$_.IdentityReference}}, @{Name='FileSystemRights';Expression={[string]$_.FileSystemRights}}, @{Name='AccessControlType';Expression={[string]$_.AccessControlType}}, IsInherited\n}`,requirements:'Windows; PowerShell 5.1 or 7. Read permission for the security descriptor. ACL entries do not account for all group membership, share permissions, or effective access.'},
  {id:'file-hash',name:'Check file integrity',category:'File Management',icon:'▱',description:'Compute a file hash and optionally compare it to an expected value.',keywords:['file hash','sha256','integrity','checksum'],cmdlets:'Get-FileHash',parameters:[text('path','File path','','Choose a file on the machine running the script.',true),choice('algorithm','Hash algorithm','SHA256',['SHA256','SHA384','SHA512'],'SHA-256 is the default.'),text('expected','Expected hash','','Optional hexadecimal digest for the selected algorithm.')],generate:v=>`Get-FileHash -LiteralPath ${q(v.path)} -Algorithm ${q(v.algorithm)}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object Algorithm, Hash, Path${v.expected.trim()?`, @{Name='Match';Expression={$_.Hash -eq ${q(v.expected)}}}`:''}`,requirements:'PowerShell 5.1 or 7; permission to read the file. A matching hash only establishes equality with the supplied digest.'},
  {id:'local-members',name:'List local group members',category:'System Information',icon:'▦',description:'Inspect membership of a local Windows group.',keywords:['local group','administrators','local members'],cmdlets:'Get-LocalGroupMember',dependencies:['Microsoft.PowerShell.LocalAccounts'],parameters:[text('group','Local group name','Administrators','Use the localized group name. Administrators is an example on English Windows.',true)],generate:v=>`Get-LocalGroupMember -Name ${q(v.group)}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object Name, ObjectClass, PrincipalSource, @{Name='SID';Expression={[string]$_.SID}}`,requirements:'Windows 10 / Server 2016 or later with LocalAccounts. Use 64-bit PowerShell on 64-bit Windows; the module is unavailable in 32-bit PowerShell there. Runs locally; access permissions apply.'},
  {id:'bitlocker',name:'Check BitLocker status',category:'System Information',icon:'◫',description:'Read volume protection and encryption status without exposing recovery protectors.',keywords:['bitlocker','encryption status','volume protection'],cmdlets:'Get-BitLockerVolume',dependencies:['BitLocker'],admin:true,parameters:[text('mountPoint','Mount point','','Optional drive letter, such as C:. Blank reads local volumes.')],generate:v=>`Get-BitLockerVolume${optional(v,'mountPoint','MountPoint')}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object MountPoint, VolumeStatus, ProtectionStatus, EncryptionPercentage`,requirements:'Windows with the BitLocker feature/module installed; administrator access. Windows PowerShell 5.1 or PowerShell 7 where the Windows module is compatible. Local volumes only; recovery passwords and KeyProtector details are excluded.'},
  {id:'defender',name:'Check Microsoft Defender status',category:'System Information',icon:'▦',description:'Read Defender-reported protection and signature state.',keywords:['defender','antivirus status','security status'],cmdlets:'Get-MpComputerStatus',dependencies:['Defender'],parameters:[],generate:v=>`Get-MpComputerStatus${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object AMServiceEnabled, AntivirusEnabled, RealTimeProtectionEnabled, AntivirusSignatureVersion, AntivirusSignatureLastUpdated`,requirements:'Windows with the Defender module and Defender services installed. Windows PowerShell 5.1 or PowerShell 7 with a compatible module. Local reported state is not a complete endpoint-security assessment.'},
  {id:'hotfix',name:'Look up installed hotfixes',category:'System Information',icon:'▦',description:'List CBS-reported hotfixes or check one KB identifier.',keywords:['hotfix','kb','windows updates'],cmdlets:'Get-HotFix',parameters:[text('kb','KB identifier','','Optional exact identifier, such as KB5030219. A missing hotfix can raise an error.')],generate:v=>`Get-HotFix${optional(v,'kb','Id')}${v.verbose?' -Verbose':''} -ErrorAction Stop | Select-Object HotFixID, Description, InstalledOn, InstalledBy`,requirements:'Windows; PowerShell 5.1 or 7. Queries Win32_QuickFixEngineering / CBS updates; this is not a complete inventory of every Windows update. Local computer only.'},
  {id:'service-details',name:'Inspect service configuration',category:'Windows Services',icon:'⚙',description:'Read service status, startup mode, and account on the local computer.',keywords:['service troubleshooting','automatic services','startup configuration','stopped services'],cmdlets:'Get-CimInstance',parameters:[text('service','Service name','','Optional exact service name, such as Spooler, not its display name. Blank lists all local services.')],generate:v=>`Get-CimInstance -ClassName Win32_Service${v.verbose?' -Verbose':''} -ErrorAction Stop${v.service.trim()?` | Where-Object { $_.Name -eq ${q(v.service)} }`:''} | Select-Object Name, DisplayName, State, StartMode, StartName`,requirements:'Windows; PowerShell 5.1 or 7; CIM cmdlets. Local computer only. StartMode Auto means automatic; State is Running or Stopped. Read-only; a restart is a separate, explicitly configured action.'}
